def hub_links(hub, state="hot", flow="both"):
    return [ln(hub, "fl", flow, 1200, state, ("book flight", "ফ্লাইট বুক")), ln(hub, "ho", flow, 1200, state, ("book hotel", "হোটেল বুক")), ln(hub, "ca", flow, 1200, state, ("rent car", "গাড়ি ভাড়া"))]


